BEGIN TRANSACTION;
CREATE TABLE features (
    signal_id      TEXT PRIMARY KEY,
    captured_at_ts REAL,   -- epoch seconds when the signal fired
    max_asof_ts    REAL,   -- newest input timestamp used (must be <= captured_at_ts)
    features_json  TEXT
);
CREATE TABLE positions (
    key        TEXT PRIMARY KEY,   -- option_symbol (single) / long_symbol (spread)
    structure  TEXT,               -- "single" | "spread"
    opened_at  TEXT,
    expiry     TEXT,
    data_json  TEXT                -- full serialized position
);
CREATE TABLE rejects (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    time      TEXT,
    symbol    TEXT,
    direction TEXT,
    stage     TEXT,
    reason    TEXT
);
CREATE TABLE shadow (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    time         TEXT,
    signal_id    TEXT,
    proba        REAL,
    would_skip   INTEGER,
    size_mult    REAL,
    actual_action TEXT
);
CREATE TABLE signals (
    signal_id   TEXT PRIMARY KEY,
    captured_at TEXT,
    symbol      TEXT,
    direction   TEXT,
    source      TEXT,
    spot        REAL
);
CREATE TABLE trades (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    signal_id     TEXT,
    structure     TEXT,    -- "single" | "spread"
    symbol        TEXT,
    direction     TEXT,
    entry_time    TEXT,
    exit_time     TEXT,
    entry_underlying REAL,
    exit_underlying  REAL,
    contract      TEXT,
    strike        REAL,
    short_strike  REAL,
    expiry        TEXT,
    qty           INTEGER,
    entry_fill    REAL,
    exit_fill     REAL,
    entry_mid     REAL,
    max_loss      REAL,
    pnl           REAL,
    r_multiple    REAL,
    entry_slippage REAL,
    exit_reason   TEXT,
    label         INTEGER  -- 1 if target hit before stop, 0 otherwise; NULL until set
);
DELETE FROM "sqlite_sequence";
COMMIT;
